// 
//SkillData에 대한 카테고리 별 캐릭터 선정
//NPC_BOY -> 공격형 (스스로 공격)
//첫 캐릭터로 슬롯에 동시에 여러개가 나오면 세진다는 부분을 어필
//대략 배수는 x1, x3, x10
//NPC_BOY_SKILL1 : 새총으로 아주 조그만 돌을 던진다. 공격력은 히어로의 절반정도
//NPC_BOY_SKILL2 : 새총으로 센 돌을 던진다.
//NPC_BOY_SKILL3 : 새총으로 아주 강력한 것을 던진다.
//NPC_GIRL -> 버프형 (공업) 
//히어로의 공격력을 올려주는 컨셉을 추가해준다.
//NPC_GIRL_SKILL1 : 히어로에게 50%의 공격력을 올려준다.
//NPC_GIRL_SKILL2 : 히어로에게 100%의 공격력을 올려준다.
//NPC_GIRL_SKILL3 : 히어로에게 200%의 공격력을 올려준다.
//NPC_MAID -> 버프형 (체력 회복) ? 체력회복이 필요한가? 이게 회복이 가능하려면
//NPC_MAID_SKILL1 : 걸레를 던진다.
//NPC_MAID_SKILL2 : 히어로에게 100%의 공격력을 올려준다.
//NPC_MAID_SKILL3 : 히어로에게 200%의 공격력을 올려준다.
